import * as THREE from 'three';
// Emitter ribbon: samples only its owner transform; GPU particle positions stay on GPU.
export class RibbonTrail {
 constructor(owner,p){this.owner=owner;this.p=p;this.points=[];this.geometry=new THREE.BufferGeometry();this.positions=new Float32Array(p.trailPoints*6);this.colors=new Float32Array(p.trailPoints*8);const indices=[];for(let i=0;i<p.trailPoints-1;i++){const n=i*2;indices.push(n,n+1,n+2,n+1,n+3,n+2);}this.geometry.setAttribute('position',new THREE.BufferAttribute(this.positions,3).setUsage(THREE.DynamicDrawUsage));this.geometry.setAttribute('color',new THREE.BufferAttribute(this.colors,4).setUsage(THREE.DynamicDrawUsage));this.geometry.setIndex(indices);this.geometry.setDrawRange(0,0);this.material=new THREE.MeshBasicMaterial({vertexColors:true,transparent:true,depthWrite:false,side:THREE.DoubleSide,blending:p.blend==='additive'?THREE.AdditiveBlending:THREE.NormalBlending});this.mesh=new THREE.Mesh(this.geometry,this.material);this.mesh.frustumCulled=false;this.mesh.userData.objectId=owner.userData.objectId;this.mesh.userData.particleTrail=true;owner.add(this.mesh);this.point=new THREE.Vector3();this.eye=new THREE.Vector3();this.tangent=new THREE.Vector3();this.side=new THREE.Vector3();this.inverse=new THREE.Matrix4();}
 update(camera,time,emitting=true){if(this.last===undefined)this.last=time;this.last=time;const p=this.p;this.owner.updateWorldMatrix(true,false);this.point.setFromMatrixPosition(this.owner.matrixWorld);const previous=this.points.at(-1);if(emitting&&(!previous||previous.position.distanceTo(this.point)>=p.trailDistance)){this.points.push({position:this.point.clone(),time});if(this.points.length>p.trailPoints)this.points.shift();}while(this.points[0]&&time-this.points[0].time>p.trailLifetime)this.points.shift();this.inverse.copy(this.owner.matrixWorld).invert();camera.getWorldPosition(this.eye);for(let i=0;i<this.points.length;i++){const row=this.points[i],a=this.points[Math.max(0,i-1)].position,b=this.points[Math.min(this.points.length-1,i+1)].position;this.tangent.subVectors(b,a);this.side.subVectors(this.eye,row.position).cross(this.tangent).normalize().multiplyScalar(p.trailWidth/2);for(let side=0;side<2;side++){this.point.copy(row.position).addScaledVector(this.side,side?1:-1).applyMatrix4(this.inverse);this.point.toArray(this.positions,(i*2+side)*3);const alpha=Math.max(0,1-(time-row.time)/p.trailLifetime);for(let c=0;c<4;c++)this.colors[(i*2+side)*4+c]=p.color[c]*(c===3?alpha:1);}}this.geometry.attributes.position.needsUpdate=this.geometry.attributes.color.needsUpdate=true;this.geometry.setDrawRange(0,Math.max(0,this.points.length-1)*6);}
 dispose(){this.mesh.removeFromParent();this.geometry.dispose();this.material.dispose();this.points=[];}
}
